package NewPac;

public class DataTypes {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		
		//Numeric type
		
		byte a = 127;
		
		System.out.println("The Value of a = " + a);
		
		short id = 1001;
		
		System.out.println("Id of the Stu:" + id);
		
		
		int value = 500;
		
		System.out.println("Value of sqFeet : "+ value);
		
		long phoneNum = 9500491323l;
		
		System.out.println("Saikiran's Phone num 91+:" + phoneNum);
		
		
		float biscuit_Price = 10.25f;
		System.out.println("Biscuit Packet Price is : Rs"+ biscuit_Price);
		
		char grade  = 'A';
		
		System.out.println("1st sem Grade:" + grade);
		
		double num = 1010.01254788888;
		
		System.out.println("num:"+ num);
		
		boolean rain = false;
		
		System.out.println("Today's Rain:" + rain);
		
		String Name = "Saikiran";
		
		System.out.println("My Name is" + " " + Name);
		
	    String city = "Erode";
		
		//char city = "a"; invalid
		
		System.out.println("City:"+ " "+ city);
		
		
		final  int c = 18;
			
		System.out.println(c);
		

	}

}
